// Regenerates hwm14_data.cpp from the verbatim NRL data files in nrl/.
// Usage: node tools/embed-data.mjs
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const files = ["hwm123114.bin", "dwm07b104i.dat", "gd2qd.dat"];
let out = `// Generated by tools/embed-data.mjs from nrl/ (NRL HWM14.123114). Do not edit.
#include "hwm14.hpp"

namespace hwm14 {
namespace {
`;
const table = [];
files.forEach((name, i) => {
  const bytes = fs.readFileSync(path.join(root, "nrl", name));
  const sha = crypto.createHash("sha256").update(bytes).digest("hex");
  out += `// ${name}: ${bytes.length} bytes, sha256 ${sha}\nconst unsigned char kFile${i}[${bytes.length}] = {`;
  for (let k = 0; k < bytes.length; k++) {
    if (k % 24 === 0) out += "\n    ";
    out += `${bytes[k]},`;
  }
  out += "\n};\n";
  table.push(`    {"${name}", kFile${i}, sizeof(kFile${i}), "${sha}"},`);
});
out += `const EmbeddedFile kFiles[] = {\n${table.join("\n")}\n};\n}  // namespace\n
const EmbeddedFile* embeddedFiles(std::size_t* count) {
    *count = sizeof(kFiles) / sizeof(kFiles[0]);
    return kFiles;
}

}  // namespace hwm14
`;
fs.writeFileSync(path.join(root, "hwm14_data.cpp"), out);
console.log(`wrote hwm14_data.cpp (${files.length} files)`);
